        /// <summary>Bolter (MV-578 rewrite of MV-539) — keeps the small-tier two-wheel drivetrain, but
        /// shares NO body silhouette with the Rusher any more: MV-539's version reused the Rusher's
        /// exact two body-cone lathes and only varied its small head spikes, invisible at gameplay
        /// camera distance. The body is now a low, wide drum (roughly twice the Rusher body's
        /// width-to-height ratio) wearing a crown of six large spikes radiating from its own equator —
        /// the drum itself is the spiked silhouette, not a smooth dome underneath a separate spiked
        /// head — plus a forward rod-launcher barrel as the weapon tell. One eye lens, per the roster's
        /// one-eye rule.</summary>
        private static void BuildBolter(Transform root, in RobotPalette p,
                                    List<MeshRenderer> eyes, List<Transform> wheels, List<Transform> legs)
        {
            wheels.Add(Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.0705f, -0.0675f), new Vector2(0.2021f, -0.0675f), new Vector2(0.235f, -0.0405f), new Vector2(0.235f, 0.0405f), new Vector2(0.2021f, 0.0675f), new Vector2(0.0705f, 0.0675f) }, 22), p.Dark, new Vector3(0f, 0.235f, -0.02f), Quaternion.Euler(0f, 0f, 90f), Vector3.one));
            wheels.Add(Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.1222f, -0.0243f), new Vector2(0.141f, 0f), new Vector2(0.1222f, 0.0243f) }, 16), p.Warm, new Vector3(0f, 0.235f, -0.02f), Quaternion.Euler(0f, 0f, 90f), Vector3.one));
            Add(root, CharacterMeshes.Beam(0.22f, 0.032f, 0.024f, 6), p.Dark, new Vector3(0f, 0.16f, 0.2f), Quaternion.Euler(60f, 0f, 0f), Vector3.one);

            // The drum: low and wide (diameter ~0.84m over a ~0.34m height — about twice the Rusher
            // body's own width-to-height ratio), not the Rusher's tall raked cone stack.
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.16f, 0f), new Vector2(0.36f, 0.05f), new Vector2(0.42f, 0.14f), new Vector2(0.414f, 0.16f) }, 28), p.Cool, new Vector3(0f, 0.32f, 0f), Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.414f, 0.16f), new Vector2(0.4f, 0.22f), new Vector2(0.28f, 0.28f), new Vector2(0.15f, 0.34f) }, 28), p.Warm, new Vector3(0f, 0.32f, 0f), Quaternion.identity, Vector3.one);

            // Six large spikes (height 0.52 — over 2x MV-539's biggest head spike at 0.22) radiating
            // from the drum's own equator (world y ~0.46, its widest point), 60 degrees apart and
            // offset 30 degrees off dead-ahead so none of them collide with the eye/barrel up front.
            const float spikeRadius = 0.40f;
            const float spikeEquatorY = 0.46f;
            for (int i = 0; i < 6; i++)
            {
                float thetaDeg = 30f + i * 60f;
                float thetaRad = thetaDeg * Mathf.Deg2Rad;
                var spikePos = new Vector3(Mathf.Sin(thetaRad) * spikeRadius, spikeEquatorY, Mathf.Cos(thetaRad) * spikeRadius);
                Add(root, CharacterMeshes.Prism(4, 0.10f, 0.006f, 0.52f, 0.1f, 0f), p.Warm,
                    spikePos, Quaternion.Euler(78f, thetaDeg, 0f), Vector3.one, "Spike");
            }

            // Eye socket, on the drum's front face.
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.1008f, 0f), new Vector2(0.1544f, 0.0158f), new Vector2(0.1625f, 0.0325f), new Vector2(0.1463f, 0.0525f) }, 24), p.Dark, new Vector3(0f, 0.62f, 0.26f), Quaternion.Euler(50f, 0f, 0f), Vector3.one);
            eyes.Add(Lens(root, CharacterMeshes.Sphere(20), new Vector3(0f, 0.6361f, 0.2792f), Quaternion.Euler(-40f, 0f, 0f), new Vector3(0.1938f, 0.1938f, 0.0625f)));

            // The weapon tell: one forward rod-launcher barrel at eye level, pointing straight down the
            // robot's own +Z (the direction BolterBolt.Fire's aim always resolves to before rotation).
            Add(root, CharacterMeshes.Beam(0.42f, 0.055f, 0.04f, 8), p.Dark, new Vector3(0f, 0.62f, 0.51f), Quaternion.Euler(90f, 0f, 0f), Vector3.one, "Barrel");
            Add(root, CharacterMeshes.Sphere(10), p.Gold, new Vector3(0f, 0.62f, 0.72f), Quaternion.identity, new Vector3(0.032f, 0.032f, 0.032f));
        }

