            wheels.Add(Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.0225f, -0.031f), new Vector2(0.0645f, -0.031f), new Vector2(0.075f, -0.0186f), new Vector2(0.075f, 0.0186f), new Vector2(0.0645f, 0.031f), new Vector2(0.0225f, 0.031f) }, 22), p.Dark, new Vector3(-0.24f, 0.075f, 0.38f), Quaternion.Euler(0f, 0f, 90f), Vector3.one));
            wheels.Add(Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.039f, -0.0112f), new Vector2(0.045f, 0f), new Vector2(0.039f, 0.0112f) }, 16), p.Dark, new Vector3(-0.24f, 0.075f, 0.38f), Quaternion.Euler(0f, 0f, 90f), Vector3.one));
